<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\CompanyOnboarding;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('COMPANY_CREATE_OWN');$uid=(int)Auth::user()['id'];if(CompanyOnboarding::current($uid)){header('Location: '.Url::to('company/profile.php'));exit;}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token. Please refresh and try again.';else try{CompanyOnboarding::createForShipper($uid,$_POST);header('Location: '.Url::to('company/profile.php?created=1'));exit;}catch(RuntimeException $e){$errors[]=$e->getMessage();}catch(Throwable $e){@file_put_contents(BASE_PATH.'/storage/logs/phase3.log','['.date('c').'] '.$e->getMessage().PHP_EOL,FILE_APPEND|LOCK_EX);$errors[]='Company setup could not be completed. Check the local error log.';}}$pageTitle='Company setup';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Set up your company</h1><p>Create the Shipper/Cargo Owner company scope for this account.</p></div><span class="badge">Verification pending after submission</span></div><?php foreach($errors as $error):?><div class="error"><?=h($error)?></div><?php endforeach;?><div class="notice">Creating this profile does not verify the company and does not grant any internal or approval role.</div><form class="card" method="post"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><div class="form-grid"><div class="field"><label for="legal_name">Legal name</label><input id="legal_name" name="legal_name" maxlength="191" required value="<?=h($_POST['legal_name']??'')?>"></div><div class="field"><label for="display_name">Display name</label><input id="display_name" name="display_name" maxlength="191" required value="<?=h($_POST['display_name']??'')?>"></div><div class="field"><label for="registration_number">Registration number <span class="muted">(optional)</span></label><input id="registration_number" name="registration_number" maxlength="96" value="<?=h($_POST['registration_number']??'')?>"></div><div class="field"><label for="registration_country">Country code</label><input id="registration_country" name="registration_country" maxlength="2" placeholder="TZ" required value="<?=h($_POST['registration_country']??'TZ')?>"></div><div class="field full"><label for="line_1">Registered address</label><input id="line_1" name="line_1" maxlength="191" required value="<?=h($_POST['line_1']??'')?>"></div><div class="field full"><label for="line_2">Address line 2 <span class="muted">(optional)</span></label><input id="line_2" name="line_2" maxlength="191" value="<?=h($_POST['line_2']??'')?>"></div><div class="field"><label for="city">City</label><input id="city" name="city" maxlength="120" value="<?=h($_POST['city']??'')?>"></div><div class="field"><label for="region">Region</label><input id="region" name="region" maxlength="120" value="<?=h($_POST['region']??'')?>"></div><div class="field"><label for="postal_code">Postal code <span class="muted">(optional)</span></label><input id="postal_code" name="postal_code" maxlength="32" value="<?=h($_POST['postal_code']??'')?>"></div></div><div class="actions"><button class="button" type="submit">Create company profile</button></div></form><?php require BASE_PATH.'/app/Views/layout/footer.php';
